1	//===- DebugInfo.h - Debug Information Helpers ------------------*- C++ -*-===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	//
9	// This file defines a bunch of datatypes that are useful for creating and
10	// walking debug info in LLVM IR form. They essentially provide wrappers around
11	// the information in the global variables that's needed when constructing the
12	// DWARF information.
13	//
14	//===----------------------------------------------------------------------===//
15	
16	#ifndef LLVM_IR_DEBUGINFO_H
17	#define LLVM_IR_DEBUGINFO_H
18	
19	#include "llvm/ADT/DenseMapInfo.h"
20	#include "llvm/ADT/STLExtras.h"
21	#include "llvm/ADT/SetVector.h"
22	#include "llvm/ADT/SmallPtrSet.h"
23	#include "llvm/ADT/SmallSet.h"
24	#include "llvm/ADT/SmallVector.h"
25	#include "llvm/ADT/TinyPtrVector.h"
26	#include "llvm/ADT/iterator_range.h"
27	#include "llvm/IR/DataLayout.h"
28	#include "llvm/IR/IntrinsicInst.h"
29	#include "llvm/IR/PassManager.h"
30	#include "llvm/Support/Compiler.h"
31	#include <optional>
32	
33	namespace llvm {
34	
35	class DbgDeclareInst;
36	class DbgValueInst;
37	class DbgVariableIntrinsic;
38	class DbgVariableRecord;
39	class Instruction;
40	class Module;
41	
42	/// Finds dbg.declare records declaring local variables as living in the
43	/// memory that 'V' points to.
44	LLVM_ABI TinyPtrVector<DbgVariableRecord *> findDVRDeclares(Value *V);
45	/// As above, for DVRValues.
46	LLVM_ABI TinyPtrVector<DbgVariableRecord *> findDVRValues(Value *V);
47	/// As above, for DVRDeclareValues.
48	LLVM_ABI TinyPtrVector<DbgVariableRecord *> findDVRDeclareValues(Value *V);
49	
50	/// Finds the debug info records describing a value.
51	LLVM_ABI void
52	findDbgUsers(Value *V,
53	             SmallVectorImpl<DbgVariableRecord *> &DbgVariableRecords);
54	/// Finds the dbg.values describing a value.
55	LLVM_ABI void
56	findDbgValues(Value *V,
57	              SmallVectorImpl<DbgVariableRecord *> &DbgVariableRecords);
58	
59	/// Find subprogram that is enclosing this scope.
60	LLVM_ABI DISubprogram *getDISubprogram(const MDNode *Scope);
61	
62	/// Produce a DebugLoc to use for each dbg.declare that is promoted to a
63	/// dbg.value.
64	LLVM_ABI DebugLoc getDebugValueLoc(DbgVariableRecord *DVR);
65	
66	/// Strip debug info in the module if it exists.
67	///
68	/// To do this, we remove all calls to the debugger intrinsics and any named
69	/// metadata for debugging. We also remove debug locations for instructions.
70	/// Return true if module is modified.
71	LLVM_ABI bool StripDebugInfo(Module &M);
72	LLVM_ABI bool stripDebugInfo(Function &F);
73	
74	/// Downgrade the debug info in a module to contain only line table information.
75	///
76	/// In order to convert debug info to what -gline-tables-only would have
77	/// created, this does the following:
78	///   1) Delete all debug intrinsics.
79	///   2) Delete all non-CU named metadata debug info nodes.
80	///   3) Create new DebugLocs for each instruction.
81	///   4) Create a new CU debug info, and similarly for every metadata node
82	///      that's reachable from the CU debug info.
83	///   All debug type metadata nodes are unreachable and garbage collected.
84	LLVM_ABI bool stripNonLineTableDebugInfo(Module &M);
85	
86	/// Update the debug locations contained within the MD_loop metadata attached
87	/// to the instruction \p I, if one exists. \p Updater is applied to Metadata
88	/// operand in the MD_loop metadata: the returned value is included in the
89	/// updated loop metadata node if it is non-null.
90	LLVM_ABI void
91	updateLoopMetadataDebugLocations(Instruction &I,
92	                                 function_ref<Metadata *(Metadata *)> Updater);
93	
94	/// Return Debug Info Metadata Version by checking module flags.
95	LLVM_ABI unsigned getDebugMetadataVersionFromModule(const Module &M);
96	
97	/// Utility to find all debug info in a module.
98	///
99	/// DebugInfoFinder tries to list all debug info MDNodes used in a module. To
100	/// list debug info MDNodes used by an instruction, DebugInfoFinder uses
101	/// processDeclare, processValue and processLocation to handle DbgDeclareInst,
102	/// DbgValueInst and DbgLoc attached to instructions. processModule will go
103	/// through all DICompileUnits in llvm.dbg.cu and list debug info MDNodes
104	/// used by the CUs.
105	class DebugInfoFinder {
106	public:
107	  /// Process entire module and collect debug info anchors.
108	  LLVM_ABI void processModule(const Module &M);
109	  /// Process a single instruction and collect debug info anchors.
110	  LLVM_ABI void processInstruction(const Module &M, const Instruction &I);
111	
112	  /// Process a DILocalVariable.
113	  LLVM_ABI void processVariable(const DILocalVariable *DVI);
114	  /// Process debug info location.
115	  LLVM_ABI void processLocation(const Module &M, const DILocation *Loc);
116	  /// Process a DbgRecord.
117	  LLVM_ABI void processDbgRecord(const Module &M, const DbgRecord &DR);
118	
119	  /// Process subprogram.
120	  LLVM_ABI void processSubprogram(DISubprogram *SP);
121	
122	  /// Clear all lists.
123	  LLVM_ABI void reset();
124	
125	private:
126	  void processCompileUnit(DICompileUnit *CU);
127	  void processGlobalVariableExpression(DIGlobalVariableExpression *GVE);
128	  void processScope(DIScope *Scope);
129	  void processType(DIType *DT);
130	  void processVariable(DIVariable *DV);
131	  void processImportedEntity(const DIImportedEntity *Import);
132	  void processMacroNode(DIMacroNode *Macro, DIMacroFile *CurrentMacroFile);
133	  bool addCompileUnit(DICompileUnit *CU);
134	  bool addGlobalVariable(DIGlobalVariableExpression *DIG);
135	  bool addScope(DIScope *Scope);
136	  bool addSubprogram(DISubprogram *SP);
137	  bool addType(DIType *DT);
138	  bool addMacro(DIMacro *Macro, DIMacroFile *MacroFile);
139	
140	public:
141	  using DIMacroEntry = std::pair<DIMacro *, DIMacroFile *>;
142	  using compile_unit_iterator =
143	      SmallVectorImpl<DICompileUnit *>::const_iterator;
144	  using subprogram_iterator = SmallVectorImpl<DISubprogram *>::const_iterator;
145	  using global_variable_expression_iterator =
146	      SmallVectorImpl<DIGlobalVariableExpression *>::const_iterator;
147	  using type_iterator = SmallVectorImpl<DIType *>::const_iterator;
148	  using scope_iterator = SmallVectorImpl<DIScope *>::const_iterator;
149	  using macro_iterator = SmallVectorImpl<DIMacroEntry>::const_iterator;
150	
151	  iterator_range<compile_unit_iterator> compile_units() const { return CUs; }
152	
153	  iterator_range<subprogram_iterator> subprograms() const { return SPs; }
154	
155	  iterator_range<global_variable_expression_iterator> global_variables() const {
156	    return GVs;
157	  }
158	
159	  iterator_range<type_iterator> types() const { return TYs; }
160	
161	  iterator_range<scope_iterator> scopes() const { return Scopes; }
162	
163	  iterator_range<macro_iterator> macros() const { return Macros; }
164	
165	  unsigned compile_unit_count() const { return CUs.size(); }
166	  unsigned global_variable_count() const { return GVs.size(); }
167	  unsigned subprogram_count() const { return SPs.size(); }
168	  unsigned type_count() const { return TYs.size(); }
169	  unsigned scope_count() const { return Scopes.size(); }
170	  unsigned macro_count() const { return Macros.size(); }
171	
172	private:
173	  SmallVector<DICompileUnit *, 8> CUs;
174	  SmallVector<DISubprogram *, 8> SPs;
175	  SmallVector<DIGlobalVariableExpression *, 8> GVs;
176	  SmallVector<DIType *, 8> TYs;
177	  SmallVector<DIScope *, 8> Scopes;
178	  SmallVector<DIMacroEntry, 8> Macros;
179	  SmallPtrSet<const MDNode *, 32> NodesSeen;
180	};
181	
182	/// Assignment Tracking (at).
183	namespace at {
184	//
185	// Utilities for enumerating storing instructions from an assignment ID.
186	//
187	/// A range of instructions.
188	using AssignmentInstRange =
189	    iterator_range<SmallVectorImpl<Instruction *>::iterator>;
190	/// Return a range of instructions (typically just one) that have \p ID
191	/// as an attachment.
192	/// Iterators invalidated by adding or removing DIAssignID metadata to/from any
193	/// instruction (including by deleting or cloning instructions).
194	LLVM_ABI AssignmentInstRange getAssignmentInsts(DIAssignID *ID);
195	
196	inline AssignmentInstRange getAssignmentInsts(const DbgVariableRecord *DVR) {
197	  assert(DVR->isDbgAssign() &&
198	         "Can't get assignment instructions for non-assign DVR!");
199	  return getAssignmentInsts(DVR->getAssignID());
200	}
201	
202	/// Return a range of dbg_assign records for which \p Inst performs the
203	/// assignment they encode.
204	inline SmallVector<DbgVariableRecord *>
205	getDVRAssignmentMarkers(const Instruction *Inst) {
206	  if (auto *ID = Inst->getMetadata(LLVMContext::MD_DIAssignID))
207	    return cast<DIAssignID>(ID)->getAllDbgVariableRecordUsers();
208	  return {};
209	}
210	
211	/// Delete the llvm.dbg.assign intrinsics linked to \p Inst.
212	LLVM_ABI void deleteAssignmentMarkers(const Instruction *Inst);
213	
214	/// Replace all uses (and attachments) of \p Old with \p New.
215	LLVM_ABI void RAUW(DIAssignID *Old, DIAssignID *New);
216	
217	/// Remove all Assignment Tracking related intrinsics and metadata from \p F.
218	LLVM_ABI void deleteAll(Function *F);
219	
220	/// Calculate the fragment of the variable in \p DAI covered
221	/// from (Dest + SliceOffsetInBits) to
222	///   to (Dest + SliceOffsetInBits + SliceSizeInBits)
223	///
224	/// Return false if it can't be calculated for any reason.
225	/// Result is set to nullopt if the intersect equals the variable fragment (or
226	/// variable size) in DAI.
227	///
228	/// Result contains a zero-sized fragment if there's no intersect.
229	LLVM_ABI bool
230	calculateFragmentIntersect(const DataLayout &DL, const Value *Dest,
231	                           uint64_t SliceOffsetInBits, uint64_t SliceSizeInBits,
232	                           const DbgVariableRecord *DVRAssign,
233	                           std::optional<DIExpression::FragmentInfo> &Result);
234	
235	/// Replace DIAssignID uses and attachments with IDs from \p Map.
236	/// If an ID is unmapped a new ID is generated and added to \p Map.
237	LLVM_ABI void remapAssignID(DenseMap<DIAssignID *, DIAssignID *> &Map,
238	                            Instruction &I);
239	
240	/// Helper struct for trackAssignments, below. We don't use the similar
241	/// DebugVariable class because trackAssignments doesn't (yet?) understand
242	/// partial variables (fragment info) as input and want to make that clear and
243	/// explicit using types. In addition, eventually we will want to understand
244	/// expressions that modify the base address too, which a DebugVariable doesn't
245	/// capture.
246	struct VarRecord {
247	  DILocalVariable *Var;
248	  DILocation *DL;
249	
250	  VarRecord(DbgVariableRecord *DVR)
251	      : Var(DVR->getVariable()), DL(getDebugValueLoc(DVR)) {}
252	  VarRecord(DILocalVariable *Var, DILocation *DL) : Var(Var), DL(DL) {}
253	  friend bool operator<(const VarRecord &LHS, const VarRecord &RHS) {
254	    return std::tie(LHS.Var, LHS.DL) < std::tie(RHS.Var, RHS.DL);
255	  }
256	  friend bool operator==(const VarRecord &LHS, const VarRecord &RHS) {
257	    return std::tie(LHS.Var, LHS.DL) == std::tie(RHS.Var, RHS.DL);
258	  }
259	};
260	
261	} // namespace at
262	
263	template <> struct DenseMapInfo<at::VarRecord> {
264	  static unsigned getHashValue(const at::VarRecord &Var) {
265	    return hash_combine(Var.Var, Var.DL);
266	  }
267	
268	  static bool isEqual(const at::VarRecord &A, const at::VarRecord &B) {
269	    return A == B;
270	  }
271	};
272	
273	namespace at {
274	/// Map of backing storage to a set of variables that are stored to it.
275	/// TODO: Backing storage shouldn't be limited to allocas only. Some local
276	/// variables have their storage allocated by the calling function (addresses
277	/// passed in with sret & byval parameters).
278	using StorageToVarsMap =
279	    DenseMap<const AllocaInst *, SmallSetVector<VarRecord, 2>>;
280	
281	/// Track assignments to \p Vars between \p Start and \p End.
282	
283	LLVM_ABI void trackAssignments(Function::iterator Start, Function::iterator End,
284	                               const StorageToVarsMap &Vars,
285	                               const DataLayout &DL, bool DebugPrints = false);
286	
287	/// Describes properties of a store that has a static size and offset into a
288	/// some base storage. Used by the getAssignmentInfo functions.
289	struct AssignmentInfo {
290	  AllocaInst const *Base;  ///< Base storage.
291	  uint64_t OffsetInBits;   ///< Offset into Base.
292	  uint64_t SizeInBits;     ///< Number of bits stored.
293	  bool StoreToWholeAlloca; ///< SizeInBits equals the size of the base storage.
294	
295	  AssignmentInfo(const DataLayout &DL, AllocaInst const *Base,
