26	
27	DIBuilder::DIBuilder(Module &m, bool AllowUnresolvedNodes, DICompileUnit *CU)
28	    : M(m), VMContext(M.getContext()), CUNode(CU),
29	      AllowUnresolvedNodes(AllowUnresolvedNodes) {
30	  if (CUNode) {
31	    if (const auto &ETs = CUNode->getEnumTypes())
32	      EnumTypes.assign(ETs.begin(), ETs.end());
33	    if (const auto &RTs = CUNode->getRetainedTypes())
34	      AllRetainTypes.assign(RTs.begin(), RTs.end());
35	    if (const auto &GVs = CUNode->getGlobalVariables())
36	      Globals.assign(GVs.begin(), GVs.end());
37	    if (const auto &IMs = CUNode->getImportedEntities())
38	      ImportedModules.assign(IMs.begin(), IMs.end());
39	    if (const auto &MNs = CUNode->getMacros())
40	      AllMacrosPerParent.insert({nullptr, {llvm::from_range, MNs}});
41	  }
42	}
43	
44	void DIBuilder::trackIfUnresolved(MDNode *N) {
45	  if (!N)
46	    return;
47	  if (N->isResolved())
48	    return;
49	
50	  assert(AllowUnresolvedNodes && "Cannot handle unresolved nodes");
51	  UnresolvedNodes.emplace_back(N);
52	}
53	
54	void DIBuilder::finalizeSubprogram(DISubprogram *SP) {
55	  auto PN = SubprogramTrackedNodes.find(SP);
56	  if (PN == SubprogramTrackedNodes.end())
57	    return;
58	
59	  SetVector<Metadata *> RetainedNodes;
60	  for (MDNode *N : llvm::concat<MDNode *>(SP->getRetainedNodes(), PN->second)) {
61	    // If the tracked node N was temporary, and the DIBuilder user replaced it
62	    // with a node that does not belong to SP or is non-local, do not add N to
63	    // SP's retainedNodes list.
64	    DILocalScope *Scope = dyn_cast_or_null<DILocalScope>(
65	        DISubprogram::getRawRetainedNodeScope(N));
66	    if (Scope && Scope->getSubprogram() == SP)
67	      RetainedNodes.insert(N);
68	  }
69	
70	  SP->replaceRetainedNodes(
71	      MDTuple::get(VMContext, RetainedNodes.getArrayRef()));
72	}
73	
74	void DIBuilder::finalize() {
75	  if (!CUNode) {
76	    assert(!AllowUnresolvedNodes &&
77	           "creating type nodes without a CU is not supported");
78	    return;
79	  }
80	
81	  if (!EnumTypes.empty())
82	    CUNode->replaceEnumTypes(
83	        MDTuple::get(VMContext, SmallVector<Metadata *, 16>(EnumTypes.begin(),
84	                                                            EnumTypes.end())));
85	
86	  SmallVector<Metadata *, 16> RetainValues;
87	  // Declarations and definitions of the same type may be retained. Some
88	  // clients RAUW these pairs, leaving duplicates in the retained types
89	  // list. Use a set to remove the duplicates while we transform the
90	  // TrackingVHs back into Values.
91	  SmallPtrSet<Metadata *, 16> RetainSet;
92	  for (const TrackingMDNodeRef &N : AllRetainTypes)
93	    if (RetainSet.insert(N).second)
94	      RetainValues.push_back(N);
95	
96	  if (!RetainValues.empty())
97	    CUNode->replaceRetainedTypes(MDTuple::get(VMContext, RetainValues));
98	
99	  for (auto *SP : AllSubprograms)
100	    finalizeSubprogram(SP);
101	  for (auto *N : RetainValues)
102	    if (auto *SP = dyn_cast<DISubprogram>(N))
103	      finalizeSubprogram(SP);
104	
105	  if (!Globals.empty())
106	    CUNode->replaceGlobalVariables(MDTuple::get(VMContext, Globals));
107	
108	  if (!ImportedModules.empty())
109	    CUNode->replaceImportedEntities(MDTuple::get(
110	        VMContext, SmallVector<Metadata *, 16>(ImportedModules.begin(),
111	                                               ImportedModules.end())));
112	
113	  for (const auto &I : AllMacrosPerParent) {
114	    // DIMacroNode's with nullptr parent are DICompileUnit direct children.
115	    if (!I.first) {
116	      CUNode->replaceMacros(MDTuple::get(VMContext, I.second.getArrayRef()));
117	      continue;
118	    }
119	    // Otherwise, it must be a temporary DIMacroFile that need to be resolved.
120	    auto *TMF = cast<DIMacroFile>(I.first);
121	    auto *MF = DIMacroFile::get(VMContext, dwarf::DW_MACINFO_start_file,
122	                                TMF->getLine(), TMF->getFile(),
123	                                getOrCreateMacroArray(I.second.getArrayRef()));
124	    replaceTemporary(llvm::TempDIMacroNode(TMF), MF);
125	  }
126	
127	  // Now that all temp nodes have been replaced or deleted, resolve remaining
128	  // cycles.
129	  for (const auto &N : UnresolvedNodes)
130	    if (N && !N->isResolved())
131	      N->resolveCycles();
132	  UnresolvedNodes.clear();
133	
134	  // Can't handle unresolved nodes anymore.
135	  AllowUnresolvedNodes = false;
136	}
137	
138	/// If N is compile unit return NULL otherwise return N.
139	static DIScope *getNonCompileUnitScope(DIScope *N) {
140	  if (!N || isa<DICompileUnit>(N))
141	    return nullptr;
142	  return cast<DIScope>(N);
143	}
144	
145	DICompileUnit *DIBuilder::createCompileUnit(
146	    DISourceLanguageName Lang, DIFile *File, StringRef Producer,
147	    bool isOptimized, StringRef Flags, unsigned RunTimeVer, StringRef SplitName,
148	    DICompileUnit::DebugEmissionKind Kind, uint64_t DWOId,
149	    bool SplitDebugInlining, bool DebugInfoForProfiling,
150	    DICompileUnit::DebugNameTableKind NameTableKind, bool RangesBaseAddress,
151	    StringRef SysRoot, StringRef SDK) {
152	
153	  assert(!CUNode && "Can only make one compile unit per DIBuilder instance");
154	  CUNode = DICompileUnit::getDistinct(
155	      VMContext, Lang, File, Producer, isOptimized, Flags, RunTimeVer,
156	      SplitName, Kind, nullptr, nullptr, nullptr, nullptr, nullptr, DWOId,
157	      SplitDebugInlining, DebugInfoForProfiling, NameTableKind,
158	      RangesBaseAddress, SysRoot, SDK);
159	
160	  // Create a named metadata so that it is easier to find cu in a module.
161	  NamedMDNode *NMD = M.getOrInsertNamedMetadata("llvm.dbg.cu");
162	  NMD->addOperand(CUNode);
163	  trackIfUnresolved(CUNode);
164	  return CUNode;
165	}
166	
167	static DIImportedEntity *
168	createImportedModule(LLVMContext &C, dwarf::Tag Tag, DIScope *Context,
169	                     Metadata *NS, DIFile *File, unsigned Line, StringRef Name,
170	                     DINodeArray Elements,
171	                     SmallVectorImpl<TrackingMDNodeRef> &ImportedModules) {
172	  if (Line)
173	    assert(File && "Source location has line number but no file");
174	  unsigned EntitiesCount = C.pImpl->DIImportedEntitys.size();
175	  auto *M = DIImportedEntity::get(C, Tag, Context, cast_or_null<DINode>(NS),
176	                                  File, Line, Name, Elements);
177	  if (EntitiesCount < C.pImpl->DIImportedEntitys.size())
178	    // A new Imported Entity was just added to the context.
179	    // Add it to the Imported Modules list.
180	    ImportedModules.emplace_back(M);
181	  return M;
182	}
